ETL_st.name='ETL'; 
ETL_st.lat=54.353743;
ETL_st.lon=-104.986864;
ETL_st.ETL=500;
ETL_st.env='con';
ETL_st.footp='RB';
%%

names_rd=fieldnames(ETL_rd);
for i=1:length(names_rd)-3
    ETL_rd.(names_rd{i})(ETL_rd.(names_rd{i})>999)=NaN;
end
ETL_rd.Properties.DimensionNames{1}='Time';
ETL_rd=retime(ETL_rd,'daily',@nanmedian);
names_rd=fieldnames(ETL_rd);
%%
datevec(ETL_rd.Time(1)) % 2008 %[output:9341b991]
datevec(ETL_rd.Time(end)) % 2022 %[output:43024dae]
prctile(ETL_rd.U_S11,[5 50 95]) % up to 41 for 95 prct %[output:5a0613e8]

plotFigControl(ETL_rd,ETL_st.name);
% 1 size cut, ok
% sc: ok, no negatives,no clear seasonal cycle
%abs: no clear seasonality
%abs exp: clear seaonal cycle with max in winter
%%
%do one time serie with both neph
P1=timerange('2008-01-01','2009-09-16');
P2=timerange('2009-09-16','2023-01-01');


ETL_rd.BsG_Sh=NaN(size(ETL_rd.BsG1_S11));
ETL_rd.BsG_Sh(P1)=ETL_rd.BsG2_S11(P1);
ETL_rd.BsG_Sh(P2)=ETL_rd.BsG1_S11(P2);


ETL_rd.BsB_Sh=NaN(size(ETL_rd.BsB_Sh));
ETL_rd.BsB_Sh(P1)=ETL_rd.BsB2_S11(P1);
ETL_rd.BsB_Sh(P2)=ETL_rd.BsB1_S11(P2);

ETL_rd.BsR_Sh=NaN(size(ETL_rd.BsR1_S11));
ETL_rd.BsR_Sh(P1)=ETL_rd.BsR2_S11(P1);
ETL_rd.BsR_Sh(P2)=ETL_rd.BsR1_S11(P2);

%Bbs
ETL_rd.BbsG_Sh=NaN(size(ETL_rd.BbsG1_S11));
ETL_rd.BbsG_Sh(P1)=ETL_rd.BbsG2_S11(P1);
ETL_rd.BbsG_Sh(P2)=ETL_rd.BbsG1_S11(P2);


ETL_rd.BbsB_Sh=NaN(size(ETL_rd.BbsB1_S11));
ETL_rd.BbsB_Sh(P1)=ETL_rd.BbsB2_S11(P1);
ETL_rd.BbsB_Sh(P2)=ETL_rd.BbsB1_S11(P2);

ETL_rd.BbsR_Sh=NaN(size(ETL_rd.BbsR1_S11));
ETL_rd.BbsR_Sh(P1)=ETL_rd.BbsR2_S11(P1);
ETL_rd.BbsR_Sh(P2)=ETL_rd.BbsR1_S11(P2);
%%
% BP detection for scat coef and backscat

names_sc={'BsB_Sh', 'BsG_Sh', 'BsR_Sh'};
break_ETL_scat_BP=change_point_analysis_Def(ETL_rd,names_sc,0.05,'ETL','scattering');
T_ETL_scat_BP=make_table_breakpoints_def(break_ETL_scat_BP);

names_bsc={'BbsB_Sh', 'BbsG_Sh', 'BbsR_Sh'};
break_ETL_bscat_BP=change_point_analysis_Def(ETL_rd,names_bsc,0.05,'ETL','Backscattering');
T_ETL_bscat_BP=make_table_breakpoints_def(break_ETL_bscat_BP);
%%
%Homogeneisation PSAP CLAP with 30.4.2012-25.3.2015
Pt=timerange('2011-08-17','2016-07-17');
ratio_med_h=nanmedian(ETL_rd.BaG1_A12_clap(Pt)./ETL_rd.BaG1_A11_psap(Pt)) % 0.98
ratio_STN_h=nanstd(ETL_rd.BaG1_A12_clap(Pt)./ETL_rd.BaG1_A11_psap(Pt)) % 
ratio_mean_h=nanmean(ETL_rd.BaG1_A12_clap(Pt)./ETL_rd.BaG1_A11_psap(Pt)) %
ratio_mean=nanmean(ETL_rd.BaG1_A12_clap(Pt))/nanmean(ETL_rd.BaG1_A11_psap(Pt)) % 1.5913
ratio_median=nanmedian(ETL_rd.BaG1_A12_clap(Pt))/nanmedian(ETL_rd.BaG1_A11_psap(Pt)) % 1.086
figure;
plot(ETL_rd.BaG1_A11_psap(Pt),ETL_rd.BaG1_A12_clap(Pt),'.');

% fit between both data: slope 0.6798x+0.15
fit_test=robustfit(ETL_rd.BaG1_A11_psap(Pt),ETL_rd.BaG1_A12_clap(Pt)); % y coor=0.0092, slope=0.9561

cte_psap1_clap3=1; % no homogeneisation

%%
% full abs data
P1=timerange('2001-01-01','2009-09-16');
P2=timerange('2009-09-16','2023-01-01');
P3=timerange('2012-01-01','2023-01-01');

ETL_rd.BaG_Ah=NaN(size(ETL_rd.BaG1_A11_psap));
ETL_rd.BaG_Ah(P1)=ETL_rd.BaG2_A11_psap(P1);
ETL_rd.BaG_Ah(P2)=ETL_rd.BaG1_A11_psap(P2);
ETL_rd.BaG_Ah(P3)=ETL_rd.BaG1_A12_clap(P3);

ETL_rd.BaB_Ah=NaN(size(ETL_rd.BaB1_A11_psap));
ETL_rd.BaB_Ah(P1)=ETL_rd.BaB2_A11_psap(P1);
ETL_rd.BaB_Ah(P2)=ETL_rd.BaB1_A11_psap(P2);
ETL_rd.BaB_Ah(P3)=ETL_rd.BaB1_A12_clap(P3);

ETL_rd.BaR_Ah=NaN(size(ETL_rd.BaR1_A11_psap));
ETL_rd.BaR_Ah(P1)=ETL_rd.BaR2_A11_psap(P1);
ETL_rd.BaR_Ah(P2)=ETL_rd.BaR1_A11_psap(P2);
ETL_rd.BaR_Ah(P3)=ETL_rd.BaR1_A12_clap(P3);
%%
% BP detection for abs
names_abs={'BaB_Ah','BaG_Ah','BaR_Ah'};
break_ETL_abs_BP=change_point_analysis_Def(ETL_rd,names_abs,0.05,'ETL','Absorption');
T_ETL_abs_BP=make_table_breakpoints_def(break_ETL_abs_BP);
%%
lambdaSC=[450;550;700];
lambdaAE=[467;530;660];

names_neph={'BsB_Sh', 'BsG_Sh', 'BsR_Sh','BbsB_Sh','BbsG_Sh','BbsR_Sh'};
ETL_expS=compute_exp_D(ETL_rd,names_neph,lambdaSC);
names_abs={'BaB_Ah','BaG_Ah','BaR_Ah'};
ETL_expA=compute_exp_D(ETL_rd,names_abs,lambdaAE);
ETL_cal=outerjoin(ETL_expS,ETL_expA);

ETL_cal.SSAG=ETL_rd.BsG_Sh./(ETL_rd.BsG_Sh+ETL_rd.BaG_Ah);

plotFigControl_cal(ETL_cal, ETL_st.name); %[output:63b582b8] %[output:152d25ee] %[output:39caa4fe]

%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg', 'expS_br', 'expS_gr'};
break_ETL_exps_BP=change_point_analysis_Def(ETL_cal,names_exps,0.05,'ETL','scattering exp'); %[output:45bdded7] %[output:9c57ba96] %[output:5c8a8c09] %[output:22cb456a]
T_ETL_exps_BP=make_table_breakpoints_def(break_ETL_exps_BP); %[output:07ddac06] %[output:5b518f6f] %[output:29474ffb] %[output:1e8ad3eb] %[output:4bfa172d] %[output:69125b31] %[output:21b3498c] %[output:5178bc69] %[output:2e012695] %[output:46f45bc0] %[output:7559a12d] %[output:463e71c9] %[output:062fb2b1] %[output:5ad810aa] %[output:214418a9] %[output:7ca9a6a8] %[output:81a79d1b] %[output:0eb6ba79] %[output:90bbfa93] %[output:6575aa31] %[output:3b5810e8] %[output:455f3ee4] %[output:31ac162e] %[output:30f086b8] %[output:041f73f1] %[output:4a058c4b] %[output:6d976dc0]

names_exps={'expA_bg', 'expA_br', 'expA_gr'};
break_ETL_exps_BP=change_point_analysis_Def(ETL_cal,names_exps,0.05,'ETL','absorption exp'); %[output:8004ced8] %[output:27304fda] %[output:479ee40d] %[output:03dede97]
T_ETL_exps_BP=make_table_breakpoints_def(break_ETL_exps_BP);

names_BbF={'BbsFg'};
break_ETL_BbF_BP=change_point_analysis_Def(ETL_cal,names_BbF,0.05,'ETL','backscat fraction'); %[output:98c7c617] %[output:95a6105a]
T_ETL_BbF_BP=make_table_breakpoints_def(break_ETL_BbF_BP);

names_SSA={'SSAG'};
break_ETL_SSA_BP=change_point_analysis_Def(ETL_cal,names_SSA,0.05,'ETL','SSA'); %[output:68bde699] %[output:5f513e27]
T_ETL_SSA_BP=make_table_breakpoints_def(break_ETL_SSA_BP);

%%

ETL_tr=outerjoin(ETL_rd,ETL_cal);
ETL_tr.y=year(ETL_tr.Time);
% begin at the beginning of a year: 2010
%end: 2025
P=timerange('2009-01-01','2023-01-01');
ETL_tr=ETL_tr(P,:);
%trend on U0_S11 has to be done: not constant U
%dry to use : also calculate exponent on dry if it is used
%AE31 not used: delete A81, only CAPS not used: deleter A12
%decide to use the time series with the max of CAPS (A00) due to better SSA: delete A11
names=fieldnames(ETL_tr);
c= startsWith(names,"U") | endsWith(names,["A11";"A12"; "S11";"psap";"clap";"ae31"]);
N=names(c);
for i=1:length(N)
    ETL_tr.(N{i})=[];
end
names=fieldnames(ETL_tr);

%PSAP 1w to 3w in April 2012: problem end of 1w PSAP
%data to invalidate form 11.11.2011 to 1.05.2012 ALREADY DONE IN RD
% % p1=timerange('2011-11-11','2012-05-01');
% % ETL_tr.BaB_A00(p1)=NaN;
% % ETL_tr.BaG_A00(p1)=NaN;
% % ETL_tr.BaR_A00(p1)=NaN;

 % compute trend only on g
ETL_tr.BaB_Ah=[];
ETL_tr.BaR_Ah=[];
ETL_tr.BsB_Sh=[];
ETL_tr.BsR_Sh=[];

ETL_tr.BbsB_Sh=[];
ETL_tr.BbsR_Sh=[];

ETL_tr.BbsFb=[];
ETL_tr.BbsFr=[];

 ETL_tr.expA_br=[];
 ETL_tr.expA_gr=[];

ETL_tr.expS_br=[];
ETL_tr.expS_gr=[];
ETL_tr.expS_bg=[];
%%
[ETL_result_MK,ETL_result_LMSlog,ETL_result_LMSlin]=all_trend_STN(ETL_tr,ETL_st); %[output:40b58adc] %[output:3133bde4] %[output:66d63567] %[output:20965274] %[output:5c195fcb] %[output:202c35a1] %[output:2e1efef6] %[output:11fa813f] %[output:2e0aebf9] %[output:43ef5448] %[output:6ae8c702] %[output:57fdfb57] %[output:0e80dfe2] %[output:55f7d80e] %[output:1ec30039] %[output:6f515711] %[output:45deaf85] %[output:0ad3854e] %[output:9347ff5a] %[output:80410787] %[output:633433e2] %[output:85b55503] %[output:8a56e8c1] %[output:991bbc39] %[output:2e8e5ddd] %[output:9df07d20] %[output:2ec1fa57] %[output:026383c0] %[output:100af378] %[output:075ae0de] %[output:656d5c70] %[output:81e6f953] %[output:1b9d1ffc] %[output:59c8f2d7] %[output:509340dc] %[output:68c45261] %[output:13152171] %[output:1a64b02d] %[output:2ad5c31b] %[output:4ef9cf6b] %[output:748696e5]

writetable(ETL_result_MK,'ETL_res_MK.txt'); %, 'delimiter',',' )
writetable(ETL_result_LMSlog,'ETL_res_LMSlog.txt'); 
writetable(ETL_result_LMSlin,'ETL_res_LMSlin.txt'); 
plot_10y_in_two(ETL_result_MK, ETL_st,'y'); %[output:7b1bcf0f] %[output:0d1670c2]
